<template>
  <div class="space-y-5">
    <div class="breadcrumbs text-sm"><ul><li><NuxtLink to="/">Home</NuxtLink></li><li><NuxtLink to="/system-audits">System audit</NuxtLink></li><li>Tender case file</li></ul></div>
    <div v-if="loading" class="flex justify-center py-20"><span class="loading loading-spinner loading-lg" /></div>
    <div v-else-if="errorMessage" class="alert alert-error"><Icon name="lucide:triangle-alert" class="h-5 w-5" />{{ errorMessage }}</div>
    <template v-else-if="record">
      <section class="card card-border bg-base-100 shadow-sm"><div class="card-body gap-5 p-6"><div class="flex flex-col justify-between gap-4 lg:flex-row"><div class="max-w-3xl"><div class="flex gap-2"><span class="font-mono text-xs text-base-content/55">{{ record.tender.tendernumber || 'Tender number pending' }}</span><span class="badge badge-success badge-sm">{{ label(record.tender.status) }}</span></div><h1 class="mt-2 text-2xl font-bold">{{ record.tender.title }}</h1><p class="mt-2 text-sm leading-6 text-base-content/60">{{ record.tender.description }}</p></div><div class="rounded-box border border-base-200 bg-base-200/40 p-4 text-sm"><p class="font-semibold">{{ record.tender.company?.name }}</p><p class="mt-1 text-base-content/55">{{ record.tender.procurement_method?.name || 'Method not set' }}</p></div></div><div class="grid gap-3 border-t border-base-200 pt-5 sm:grid-cols-4"><div><p class="text-xs text-base-content/50">Created</p><p class="mt-1 font-semibold">{{ dateTime(record.tender.created_at) }}</p></div><div><p class="text-xs text-base-content/50">Published</p><p class="mt-1 font-semibold">{{ dateTime(record.tender.published_at) }}</p></div><div><p class="text-xs text-base-content/50">APP lines</p><p class="mt-1 font-semibold">{{ record.source_app_items?.length || 0 }}</p></div><div><p class="text-xs text-base-content/50">Audit events</p><p class="mt-1 font-semibold">{{ record.timeline?.length || 0 }}</p></div></div></div></section>

      <section class="card card-border bg-base-100 shadow-sm"><div class="card-body p-5"><div class="flex flex-wrap justify-between gap-3"><div><h2 class="card-title text-lg">Procurement process</h2><p class="mt-1 text-sm text-base-content/55">The complete cross-entity audit case file, grouped by statutory process stage.</p></div><span class="badge badge-outline">{{ completeCount }} stages complete</span></div><div class="mt-5 overflow-x-auto"><ul class="steps min-w-max"><li v-for="step in record.process_steps" :key="step.key" :class="['step px-3 text-xs', step.status === 'COMPLETE' ? 'step-success' : step.status === 'IN_PROGRESS' ? 'step-warning' : '']"><a :href="`#${step.key}`">{{ step.title }}</a></li></ul></div></div></section>

      <section class="space-y-4"><details v-for="(step, index) in record.process_steps" :id="step.key" :key="step.key" class="collapse collapse-arrow scroll-mt-5 border border-base-300 bg-base-100 shadow-sm" :open="step.status === 'IN_PROGRESS' || index === 0"><summary class="collapse-title p-5"><div class="flex flex-col justify-between gap-3 pr-7 sm:flex-row sm:items-center"><div class="flex gap-3"><span class="grid h-9 w-9 shrink-0 place-items-center rounded-full bg-base-200 font-bold">{{ index + 1 }}</span><div><h2 class="font-bold">{{ step.title }}</h2><p class="mt-1 text-sm font-normal text-base-content/55">{{ step.description }}</p></div></div><span :class="['badge badge-sm', step.status === 'COMPLETE' ? 'badge-success' : step.status === 'IN_PROGRESS' ? 'badge-warning' : 'badge-ghost']">{{ label(step.status) }}</span></div></summary><div class="collapse-content border-t border-base-200 p-5"><div class="mb-5 flex flex-wrap gap-2"><span v-for="(value, key) in step.summary" :key="key" class="badge badge-ghost"><strong class="mr-1">{{ valueText(value) }}</strong>{{ label(key) }}</span></div><div v-if="step.key === 'submissions'" class="overflow-x-auto"><table class="table table-sm"><thead><tr><th>Bidder</th><th>Status</th><th>Submitted</th><th class="text-right">Evidence</th></tr></thead><tbody><tr v-for="bid in step.records.bids" :key="bid.uuid"><td>{{ bid.supplier?.name || 'Unknown bidder' }}</td><td>{{ label(bid.status) }}</td><td>{{ dateTime(bid.submitted_at) }}</td><td class="text-right"><button class="btn btn-sm" :disabled="!bid.response_available" @click="openResponse(bid)"><Icon name="lucide:eye" class="h-4 w-4" />{{ bid.response_available ? 'View response' : 'Not opened' }}</button></td></tr></tbody></table></div><AuditEvidence v-else :value="step.records" /></div></details></section>
    </template>

    <dialog ref="responseDialog" class="modal"><div class="modal-box max-w-6xl"><div class="flex justify-between gap-4"><div><h2 class="text-xl font-bold">Opened bidder response</h2><p class="mt-1 text-sm text-base-content/55">{{ selectedBid?.supplier?.name }} · read-only evidence</p></div><form method="dialog"><button class="btn btn-sm btn-circle btn-ghost">✕</button></form></div><div v-if="responseLoading" class="flex justify-center py-16"><span class="loading loading-spinner loading-lg" /></div><div v-else-if="responseError" class="alert alert-error mt-5">{{ responseError }}</div><div v-else-if="responseRecord" class="mt-5 space-y-4"><div v-if="!responseRecord.available" class="alert alert-warning">{{ responseRecord.reason }}</div><template v-else><div class="alert alert-info text-sm"><Icon name="lucide:shield-check" class="h-5 w-5" />Opened content only; encryption keys and sealed envelopes remain protected.</div><details class="collapse collapse-arrow border border-base-200" open><summary class="collapse-title font-semibold">Technical response</summary><div class="collapse-content"><AuditEvidence :value="responseRecord.technical_response" /></div></details><details class="collapse collapse-arrow border border-base-200"><summary class="collapse-title font-semibold">Financial response</summary><div class="collapse-content"><AuditEvidence :value="responseRecord.financial_response" /></div></details><details class="collapse collapse-arrow border border-base-200"><summary class="collapse-title font-semibold">Evaluation responses</summary><div class="collapse-content"><AuditEvidence :value="responseRecord.evaluations" /></div></details></template></div></div><form method="dialog" class="modal-backdrop"><button>Close</button></form></dialog>
  </div>
</template>

<script setup>
definePageMeta({ layout: 'default' }); useHead({ title: 'Tender audit case file' })
const route = useRoute(); const api = useSystemAuditHelper(); const { can } = useCheckPermission()
const loading = ref(true); const errorMessage = ref(''); const record = ref(null); const responseDialog = ref(null); const responseLoading = ref(false); const responseError = ref(''); const responseRecord = ref(null); const selectedBid = ref(null)
const completeCount = computed(() => record.value?.process_steps?.filter(step => step.status === 'COMPLETE').length || 0)
const label = value => String(value || '').replaceAll('_', ' ').toLowerCase().replace(/\b\w/g, letter => letter.toUpperCase())
const valueText = value => typeof value === 'boolean' ? (value ? 'Yes' : 'No') : value
const dateTime = value => value ? new Intl.DateTimeFormat('en-ZW', { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(value)) : '—'
const openResponse = async bid => { selectedBid.value = bid; responseRecord.value = null; responseError.value = ''; responseLoading.value = true; responseDialog.value?.showModal(); const { data, error } = await api.getBidResponse(route.params.uuid, bid.uuid); responseLoading.value = false; if (error || data?.status === false) responseError.value = error?.data?.message || data?.message || 'The bidder response could not be loaded.'; else responseRecord.value = data.data }
onMounted(async () => { if (!can('can.access.systemaudits')) { errorMessage.value = 'You do not have permission to view system audits.'; loading.value = false; return } const { data, error } = await api.getTender(route.params.uuid); loading.value = false; if (error || data?.status === false) errorMessage.value = error?.data?.message || data?.message || 'Tender audit case file could not be loaded.'; else record.value = data.data })
</script>
